  "confidence": 0.84,
  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["R9", "R20", "R4", "R14"],
      "pins": ["J2.20", "J2.22", "J2.19", "J2.21"],
      "nets": ["/NET0004", "/NET0037", "/NET0014", "/NET0022", "/NET0027", "/NET0042"],
      "observed": "The 0 Ω links R9 and R20 connect the PWM1 path to both M5Stack bus pins 20 and 22. Likewise, 0 Ω links R4 and R14 connect the PWM2 path to both bus pins 19 and 21. Each pair of bus GPIO pins is therefore shorted together.",
      "expected": "Only the jumper mapping appropriate to the M5Stack Core variant should be shorted; the alternate mapping should remain open. The specification describes the mapping as selected by assembly-time jumper population.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0004\") ... (node (ref \"J2\") (pin \"20\")) ... (node (ref \"R20\") (pin \"2\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0037\") ... (node (ref \"J2\") (pin \"22\")) ... (node (ref \"R9\") (pin \"2\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0014\") ... (node (ref \"R20\") (pin \"1\")) (node (ref \"R21\") (pin \"2\")) (node (ref \"R9\") (pin \"1\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0022\") ... (node (ref \"J2\") (pin \"19\")) ... (node (ref \"R4\") (pin \"2\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0027\") ... (node (ref \"J2\") (pin \"21\")) ... (node (ref \"R14\") (pin \"2\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0042\") (node (ref \"R11\") (pin \"2\")) (node (ref \"R14\") (pin \"1\")) (node (ref \"R4\") (pin \"1\")))"
        },
        {
          "source": "spec",
          "quote": "R9–R12 | 0 Ω (jumpers) | Select which M5Stack bus pin (pin 19/21 for ch.1, pin 20/22 for ch.2) supplies PWM1/PWM2"
        },
        {
          "source": "spec",
          "quote": "Short R10, R10 for Core2 and CoreS3 / Short R9, R11 for others"
        }
      ],
      "impact": "The selected PWM outputs also electrically join alternate M5Stack GPIO pins. This can cause GPIO contention or incorrect operation when a Core variant uses one of the joined pins for another function.",
      "confidence": 0.84
    }
  ],
  "summary": "The netlist connects both alternative GPIO mappings for each PWM channel through 0 Ω links, shorting bus pins 19/21 and 20/22. The specification calls for selecting the mapping for the Core variant rather than connecting both alternatives."
}

